let AVG_ATTACK = TEAMS.reduce((s, t) => s + t.attack, 0) / TEAMS.length;
let AVG_DEFENSE = TEAMS.reduce((s, t) => s + t.defense, 0) / TEAMS.length;
function recomputeLeagueAverages() {
  AVG_ATTACK = TEAMS.reduce((s, t) => s + t.attack, 0) / TEAMS.length;
  AVG_DEFENSE = TEAMS.reduce((s, t) => s + t.defense, 0) / TEAMS.length;
}
// Merges real ratings fetched from a live-data backend (see backend/main.py) into the
// existing TEAMS objects in place — every function below reads from TEAMS_BY_ID, so a
// mutate-in-place + recompute-averages is enough to make the whole engine "go live"
// without threading team data through every function signature.
function applyLiveTeamRatings(liveTeams) {
  let matched = 0;
  liveTeams.forEach((lt) => {
    const local = TEAMS_BY_ID[lt.id] || TEAMS.find((t) => t.short === lt.short);
    if (!local) return;
    if (typeof lt.attack === "number") local.attack = lt.attack;
    if (typeof lt.defense === "number") local.defense = lt.defense;
    if (typeof lt.homeAdv === "number") local.homeAdv = lt.homeAdv;
    matched++;
  });
  recomputeLeagueAverages();
  return matched;
}

