// KICK-OFF: Friday 21 August 2026, 20:00 BST (19:00 UTC) — Arsenal vs Coventry.
const KICKOFF = new Date("2026-08-21T19:00:00Z");
const SEASON_ROUNDS = 38;

function generateSchedule(order) {
  const n = order.length, half = n / 2;
  let arr = order.slice();
  const rounds = [];
  for (let r = 0; r < n - 1; r++) {
    const matches = [];
    for (let i = 0; i < half; i++) {
      const a = arr[i], b = arr[n - 1 - i];
      matches.push(r % 2 === 0 ? { home: a, away: b } : { home: b, away: a });
    }
    rounds.push(matches);
    arr = [arr[0], arr[n - 1], ...arr.slice(1, n - 1)];
  }
  const secondLeg = rounds.map((rd) => rd.map((m) => ({ home: m.away, away: m.home })));
  return [...rounds, ...secondLeg];
}
const SCHEDULE_ORDER = ["ars", "mci", "hul", "new", "bha", "bre", "ful", "nfo", "eve", "ips", "sun", "cry", "lee", "che", "tot", "avl", "liv", "mun", "bou", "cov"];
const SCHEDULE = generateSchedule(SCHEDULE_ORDER).map((matches, i) => ({
  round: i + 1,
  real: i === 0,
  weekOf: new Date(KICKOFF.getTime() + i * 7 * 86400000),
  matches: matches.map((m) => ({ ...m, id: `mw${i + 1}-${m.home}-${m.away}` })),
}));
const ALL_FIXTURES = SCHEDULE.flatMap((r) => r.matches.map((m) => ({ ...m, round: r.round })));

// ===========================================================================
// MODEL ENGINE — Dixon-Coles bivariate Poisson + Monte Carlo season sim
// ===========================================================================
function seededRandom(str) {
  let h = 0;
  for (let i = 0; i < str.length; i++) h = (Math.imul(31, h) + str.charCodeAt(i)) | 0;
  return ((h >>> 0) % 100000) / 100000;
}
function factorial(n) { let f = 1; for (let i = 2; i <= n; i++) f *= i; return f; }
function poissonPMF(lambda, k) { return (Math.pow(lambda, k) * Math.exp(-lambda)) / factorial(k); }
function poissonSampleFromU(lambda, u) {
  let p = Math.exp(-lambda), cum = p, k = 0;
  while (u > cum && k < 25) { k++; p *= lambda / k; cum += p; }
  return k;
}
// Dixon-Coles low-score correlation adjustment.
function dcTau(x, y, lambda, mu, rho) {
  if (x === 0 && y === 0) return 1 - lambda * mu * rho;
  if (x === 0 && y === 1) return 1 + lambda * rho;
  if (x === 1 && y === 0) return 1 + mu * rho;
  if (x === 1 && y === 1) return 1 - rho;
  return 1;
}
function alpha(team) { return team.attack / AVG_ATTACK; }
function beta(team) { return AVG_DEFENSE / team.defense; }
function formMultiplier(team, weight) {
  if (!team.form) return 1;
  const pts = team.form.reduce((s, r) => s + (r === "W" ? 3 : r === "D" ? 1 : 0), 0);
  const score = pts / 15;
  return 1 + (score - 0.5) * 0.3 * (weight / 100);
}
const LEAGUE_HOME_GOALS = 1.55, LEAGUE_AWAY_GOALS = 1.30, GLOBAL_HOME_BONUS = 0.20;
function matchLambdas(home, away, settings) {
  const homeBoost = 1 + (settings.homeAdvWeight / 100) * GLOBAL_HOME_BONUS * (0.6 + (home.homeAdv / 100) * 0.8);
  const awayDamp = 1 - (settings.homeAdvWeight / 100) * 0.05;
  let lambdaHome = LEAGUE_HOME_GOALS * alpha(home) * beta(away) * homeBoost * formMultiplier(home, settings.formWeight);
  let lambdaAway = LEAGUE_AWAY_GOALS * alpha(away) * beta(home) * awayDamp * formMultiplier(away, settings.formWeight);
  return { lambdaHome: Math.min(4.2, Math.max(0.15, lambdaHome)), lambdaAway: Math.min(4.2, Math.max(0.15, lambdaAway)) };
}
function scoreMatrix(lambdaHome, lambdaAway, rho, maxGoals = 6) {
  const grid = [];
  let total = 0;
  for (let x = 0; x <= maxGoals; x++) {
    const row = [];
    for (let y = 0; y <= maxGoals; y++) {
      const p = Math.max(0, dcTau(x, y, lambdaHome, lambdaAway, rho) * poissonPMF(lambdaHome, x) * poissonPMF(lambdaAway, y));
      row.push(p); total += p;
    }
    grid.push(row);
  }
  return grid.map((row) => row.map((p) => p / total));
}
function marketProbs(grid) {
  let pHome = 0, pDraw = 0, pAway = 0, pBTTS = 0, pOver = 0, csHome = 0, csAway = 0;
  const scorelines = [];
  grid.forEach((row, x) => row.forEach((p, y) => {
    if (x > y) pHome += p; else if (x === y) pDraw += p; else pAway += p;
    if (x > 0 && y > 0) pBTTS += p;
    if (x + y >= 3) pOver += p;
    if (y === 0) csHome += p; // away side failed to score -> home clean sheet
    if (x === 0) csAway += p; // home side failed to score -> away clean sheet
    scorelines.push({ score: `${x}-${y}`, p });
  }));
  scorelines.sort((a, b) => b.p - a.p);
  return { pHome, pDraw, pAway, pBTTS, pUnder: 1 - pOver, pOver, csHome, csAway, top: scorelines.slice(0, 5) };
}
function predictMatch(homeId, awayId, settings) {
  const home = TEAMS_BY_ID[homeId], away = TEAMS_BY_ID[awayId];
  const { lambdaHome, lambdaAway } = matchLambdas(home, away, settings);
  const grid = scoreMatrix(lambdaHome, lambdaAway, settings.rho);
  const m = marketProbs(grid);
  // FPL-style captaincy score: expected goals weighted toward sides more likely to win.
  const captainHome = lambdaHome * (0.4 + 0.6 * m.pHome);
  const captainAway = lambdaAway * (0.4 + 0.6 * m.pAway);
  return { home, away, lambdaHome, lambdaAway, grid, captainHome, captainAway, ...m };
}
const SEASON_JITTER = 0.25; // ± attack-strength wobble applied once per simulated season, see comment below
function simulateSeason(settings, nSims, seed) {
  const positionCounts = {}, pointsSum = {}, gdSum = {};
  TEAMS.forEach((t) => { positionCounts[t.id] = new Array(20).fill(0); pointsSum[t.id] = 0; gdSum[t.id] = 0; });
  for (let s = 0; s < nSims; s++) {
    // Real squads carry pre-season uncertainty a pure match-to-match Poisson model can't see
    // (injuries, new signings bedding in, a summer of hype that doesn't translate). Without this,
    // a modest per-match edge compounds over 38 games into a ~98%+ "certain" title favourite before
    // a ball is kicked — which is a calibration bug, not confidence. A single seeded attack-strength
    // jitter per team per simulated season fixes that, while matchLambdas() and single-match
    // predictions (predictMatch) stay untouched and fully deterministic for a given fixture.
    const jitteredTeams = {};
    TEAMS.forEach((t) => {
      const u = seededRandom(`${seed}-${s}-${t.id}-jitter`);
      jitteredTeams[t.id] = { ...t, attack: t.attack * (1 + (u - 0.5) * 2 * SEASON_JITTER) };
    });
    const pts = {}, gf = {}, ga = {};
    TEAMS.forEach((t) => { pts[t.id] = 0; gf[t.id] = 0; ga[t.id] = 0; });
    ALL_FIXTURES.forEach((f, idx) => {
      const home = jitteredTeams[f.home], away = jitteredTeams[f.away];
      const { lambdaHome, lambdaAway } = matchLambdas(home, away, settings);
      const uH = seededRandom(`${seed}-${idx}-${s}-h`), uA = seededRandom(`${seed}-${idx}-${s}-a`);
      const gH = poissonSampleFromU(lambdaHome, uH), gA = poissonSampleFromU(lambdaAway, uA);
      gf[f.home] += gH; ga[f.home] += gA; gf[f.away] += gA; ga[f.away] += gH;
      if (gH > gA) pts[f.home] += 3; else if (gH < gA) pts[f.away] += 3; else { pts[f.home] += 1; pts[f.away] += 1; }
    });
    const ranking = TEAMS.map((t) => ({ id: t.id, pts: pts[t.id], gd: gf[t.id] - ga[t.id], gf: gf[t.id] }))
      .sort((a, b) => b.pts - a.pts || b.gd - a.gd || b.gf - a.gf);
    ranking.forEach((r, pos) => { positionCounts[r.id][pos]++; pointsSum[r.id] += r.pts; gdSum[r.id] += r.gd; });
  }
  return TEAMS.map((t) => {
    const pc = positionCounts[t.id];
    return {
      id: t.id, team: t,
      titleProb: pc[0] / nSims,
      top4Prob: pc.slice(0, 4).reduce((a, b) => a + b, 0) / nSims,
      relegProb: pc.slice(17, 20).reduce((a, b) => a + b, 0) / nSims,
      avgPoints: pointsSum[t.id] / nSims,
      avgGD: gdSum[t.id] / nSims,
    };
  }).sort((a, b) => b.avgPoints - a.avgPoints);
}
// One real seeded run of the season, returned as cumulative points per matchweek for one team —
// used for the landing page's "Insights Spotlight" sparkline (a genuine simulated path, not fake trend data).
function singleSeasonTrajectory(teamId, settings, seed) {
  let pts = 0;
  return SCHEDULE.map((round) => {
    round.matches.forEach((f) => {
      if (f.home !== teamId && f.away !== teamId) return;
      const { lambdaHome, lambdaAway } = matchLambdas(TEAMS_BY_ID[f.home], TEAMS_BY_ID[f.away], settings);
      const uH = seededRandom(`${seed}-${f.id}-h`), uA = seededRandom(`${seed}-${f.id}-a`);
      const gH = poissonSampleFromU(lambdaHome, uH), gA = poissonSampleFromU(lambdaAway, uA);
      const won = f.home === teamId ? gH > gA : gA > gH;
      const draw = gH === gA;
      pts += won ? 3 : draw ? 1 : 0;
    });
    return { round: round.round, pts };
  });
}
const DEFAULT_SETTINGS = { homeAdvWeight: 55, formWeight: 50, rho: -0.11 };

// ===========================================================================
// FORMAT HELPERS
// ===========================================================================
function pct(v) { return `${Math.round(v * 100)}%`; }
function ordinal(n) { const s = ["th", "st", "nd", "rd"], v = n % 100; return n + (s[(v - 20) % 10] || s[v] || s[0]); }
function formatCountdown(totalSeconds) {
  if (totalSeconds <= 0) return "LIVE";
  const d = Math.floor(totalSeconds / 86400), h = Math.floor((totalSeconds % 86400) / 3600);
  const m = Math.floor((totalSeconds % 3600) / 60), s = Math.floor(totalSeconds % 60);
  const pad = (n) => String(n).padStart(2, "0");
  return d > 0 ? `${d}d ${pad(h)}h ${pad(m)}m` : `${pad(h)}:${pad(m)}:${pad(s)}`;
}
function exportCSV(rows, filename) {
  const blob = new Blob([rows], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url; a.download = filename; document.body.appendChild(a); a.click(); a.remove();
  URL.revokeObjectURL(url);
}
function tooltipStyle() { return { fontSize: 12, borderRadius: 8, border: `1px solid ${C.border}`, background: C.surface, color: C.text }; }
function axisTick() { return { fontSize: 11, fill: C.sub }; }

// ===========================================================================
// LIVE DATA — talks to backend/main.py (the FastAPI proxy), never the FPL
// API directly. This artifact's sandbox blocks arbitrary outbound fetch()
// entirely, and the FPL API itself has no CORS headers, so this call will
// only ever succeed once EPLPredictorDashboard is running somewhere with
// real network access AND pointed at a live instance of that proxy.
// ===========================================================================
async function fetchLiveTeams(apiBase) {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 6000);
  try {
    const res = await fetch(`${apiBase.replace(/\/$/, "")}/api/teams`, { signal: controller.signal });
    clearTimeout(timeout);
    if (!res.ok) throw new Error(`Proxy returned ${res.status}`);
    const data = await res.json();
    if (!Array.isArray(data.teams)) throw new Error("Unexpected response shape");
    return { ok: true, teams: data.teams, source: data.source, fetchedAt: data.fetchedAt };
  } catch (err) {
    clearTimeout(timeout);
    return { ok: false, error: err.name === "AbortError" ? "Timed out reaching the proxy" : err.message };
  }
}

