// ===========================================================================
// RUN BUTTON + STAGED LOADER (the "you press go" moment)
// ===========================================================================
function useStagedRun(steps, stepMs, onDone) {
  const [running, setRunning] = useState(false);
  const [step, setStep] = useState(0);
  function run() {
    if (running) return;
    setRunning(true); setStep(0);
    let i = 0;
    const iv = setInterval(() => {
      i++;
      if (i >= steps.length) { clearInterval(iv); setRunning(false); setStep(0); onDone(); }
      else setStep(i);
    }, stepMs);
  }
  return { running, step, run };
}
function RunButton({ onClick, running, label, runningLabel = "Crunching…" }) {
  return (
    <button onClick={onClick} disabled={running} className="glow-btn flex items-center justify-center gap-2 px-5 py-3 rounded-xl font-bold fs-12 uppercase tracking-wide w-full sm:w-auto"
      style={{ background: running ? C.surfaceAlt : `linear-gradient(90deg, ${C.limeNeon}, ${C.cyan})`, color: running ? C.sub : C.purpleDark, border: `1px solid ${running ? C.border : "transparent"}`, cursor: running ? "default" : "pointer" }}>
      <SoccerBall size={18} spinning={running} id={`btn-${label}`} />
      {running ? runningLabel : label}
    </button>
  );
}
function StagedLoader({ steps, step }) {
  const pct100 = Math.min(100, Math.round(((step + 1) / steps.length) * 100));
  return (
    <div className="pop-in rounded-xl p-5 text-center" style={{ background: C.surfaceAlt, border: `1px solid ${C.border}` }}>
      <div className="flex justify-center mb-3"><SoccerBall size={34} spinning id="loader-ball" /></div>
      <div className="epl-mono fs-12 font-semibold" style={{ color: C.purple }}>{steps[step]}</div>
      <div className="w-full rounded-full overflow-hidden mt-3" style={{ height: 8, background: C.surface, border: `1px solid ${C.border}` }}>
        <div className="fill-bar h-full rounded-full" style={{ width: `${pct100}%`, background: `linear-gradient(90deg, ${C.limeNeon}, ${C.cyan})`, transition: "width 340ms ease" }} />
      </div>
    </div>
  );
}

// ===========================================================================
// SIGNATURE: TELETEXT TICKER
// ===========================================================================
function TeletextTicker({ fixtures, settings, tick }) {
  const rows = useMemo(() => fixtures.map((f) => {
    const p = predictMatch(f.home, f.away, settings);
    const top = p.top[0];
    return { f, p, top };
  }), [fixtures, settings]);
  const idx = Math.floor(tick / 4) % rows.length;
  const page = 445;
  // eslint-disable-next-line no-unused-vars
  const _refresh = tick; // re-render trigger so the clock ticks live
  const clock = new Date().toUTCString().slice(17, 22);
  const colors = ["#39FF6A", "#FFD23F", "#4FD8FF", "#FF6B6B", "#FFFFFF"];
  return (
    <div className="rounded-xl overflow-hidden" style={{ background: C.teletextBg, border: `1px solid ${C.border}` }}>
      <div className="flex justify-between items-center px-3 py-1.5" style={{ background: "#1531A8" }}>
        <span className="epl-mono fs-11 font-bold" style={{ color: "#FFD23F" }}>P{page} CEEFAX FOOTBALL</span>
        <span className="epl-mono fs-11 font-bold flex items-center gap-1.5" style={{ color: "#39FF6A" }}>
          <span className="live-dot inline-block rounded-full" style={{ width: 6, height: 6, background: "#39FF6A" }} />LIVE MODEL · {clock}
        </span>
      </div>
      <div className="px-3 py-3">
        <div className="epl-mono fs-10 mb-2" style={{ color: "#4FD8FF" }}>MATCHWEEK 1 KICK-OFF PREDICTIONS — {rows.length} FIXTURES</div>
        {rows.map(({ f, p, top }, i) => {
          const active = i === idx;
          return (
            <div key={f.id} className="epl-mono flex items-center justify-between py-1" style={{ opacity: active ? 1 : 0.45, fontSize: 13, transition: "opacity 300ms" }}>
              <span style={{ color: colors[i % colors.length] }}>{f.homeT.short}</span>
              <span style={{ color: "#FFFFFF" }}>{active ? top.score : "· ·"}</span>
              <span style={{ color: colors[(i + 2) % colors.length] }}>{f.awayT.short}</span>
              <span className="fs-10" style={{ color: "#FFD23F", width: 84, textAlign: "right" }}>
                {pct(Math.max(p.pHome, p.pDraw, p.pAway))} {p.pHome > p.pAway && p.pHome > p.pDraw ? "1" : p.pAway > p.pHome && p.pAway > p.pDraw ? "2" : "X"}
              </span>
            </div>
          );
        })}
        <div className="epl-mono fs-9 mt-2 tt-cursor" style={{ color: "#4FD8FF" }}>█ NEXT PAGE 446: FULL TABLE ▸</div>
      </div>
    </div>
  );
}

// ===========================================================================
// CHARTS
// ===========================================================================
function GoalDistributionChart({ prediction }) {
  const tail = (lambda) => 1 - [0, 1, 2, 3, 4].reduce((s, i) => s + poissonPMF(lambda, i), 0);
  const data = Array.from({ length: 6 }, (_, k) => ({
    goals: k === 5 ? "5+" : String(k),
    Home: k === 5 ? tail(prediction.lambdaHome) : poissonPMF(prediction.lambdaHome, k),
    Away: k === 5 ? tail(prediction.lambdaAway) : poissonPMF(prediction.lambdaAway, k),
  }));
  return (
    <ResponsiveContainer width="100%" height={220}>
      <BarChart data={data} margin={{ left: -18, top: 4 }}>
        <CartesianGrid strokeDasharray="3 3" stroke={C.gridline} vertical={false} />
        <XAxis dataKey="goals" tick={axisTick()} axisLine={{ stroke: C.border }} tickLine={false} />
        <YAxis tick={axisTick()} axisLine={false} tickLine={false} tickFormatter={(v) => `${Math.round(v * 100)}%`} />
        <Tooltip contentStyle={tooltipStyle()} formatter={(v) => `${(v * 100).toFixed(1)}%`} />
        <Legend wrapperStyle={{ fontSize: 11 }} />
        <Bar dataKey="Home" fill={prediction.home.color} radius={[4, 4, 0, 0]} />
        <Bar dataKey="Away" fill={prediction.away.color} radius={[4, 4, 0, 0]} />
      </BarChart>
    </ResponsiveContainer>
  );
}
function TeamRadar({ home, away }) {
  const data = [
    { axis: "Attack", Home: home.attack, Away: away.attack },
    { axis: "Defence", Home: home.defense, Away: away.defense },
    { axis: "Home Edge", Home: home.homeAdv, Away: away.homeAdv },
    { axis: "Discipline", Home: home.discipline, Away: away.discipline },
    { axis: "Form", Home: home.form ? home.form.reduce((s, r) => s + (r === "W" ? 20 : r === "D" ? 7 : 0), 0) : 50, Away: away.form ? away.form.reduce((s, r) => s + (r === "W" ? 20 : r === "D" ? 7 : 0), 0) : 50 },
  ];
  return (
    <ResponsiveContainer width="100%" height={240}>
      <RadarChart data={data} outerRadius="72%">
        <PolarGrid stroke={C.gridline} />
        <PolarAngleAxis dataKey="axis" tick={{ fontSize: 11, fill: C.sub }} />
        <PolarRadiusAxis tick={false} axisLine={false} domain={[0, 100]} />
        <Radar name={home.short} dataKey="Home" stroke={home.color} fill={home.color} fillOpacity={0.28} />
        <Radar name={away.short} dataKey="Away" stroke={away.color} fill={away.color} fillOpacity={0.28} />
        <Legend wrapperStyle={{ fontSize: 11 }} />
        <Tooltip contentStyle={tooltipStyle()} />
      </RadarChart>
    </ResponsiveContainer>
  );
}
function CorrectScoreGrid({ prediction }) {
  const g = prediction.grid; // 7x7, indices 0-6 goals
  // cell(x,y): x/y of 5 means "5 or more" — sum the tail rows/columns (indices 5 and 6) properly.
  const cell = (x, y) => {
    const xs = x === 5 ? [5, 6] : [x];
    const ys = y === 5 ? [5, 6] : [y];
    let p = 0;
    xs.forEach((xi) => ys.forEach((yi) => { p += g[xi][yi]; }));
    return p;
  };
  const cells = [0, 1, 2, 3, 4, 5].flatMap((x) => [0, 1, 2, 3, 4, 5].map((y) => cell(x, y)));
  const max = Math.max(...cells);
  return (
    <div>
      <div className="grid gap-1" style={{ gridTemplateColumns: `44px repeat(6, 1fr)` }}>
        <div />
        {[0, 1, 2, 3, 4, 5].map((y) => <div key={y} className="fs-10 text-center font-semibold" style={{ color: C.sub }}>{y === 5 ? "5+" : y}</div>)}
        {[0, 1, 2, 3, 4, 5].map((x) => (
          <React.Fragment key={x}>
            <div className="fs-10 flex items-center font-semibold" style={{ color: C.sub }}>{x === 5 ? "5+" : x}</div>
            {[0, 1, 2, 3, 4, 5].map((y) => {
              const p = cell(x, y);
              const intensity = Math.min(1, p / max);
              return (
                <div key={y} className="rounded fs-10 flex items-center justify-center epl-mono" style={{ height: 28, background: `rgba(27,94,56,${0.08 + intensity * 0.75})`, color: intensity > 0.5 ? "#fff" : C.text }}>
                  {(p * 100).toFixed(0)}
                </div>
              );
            })}
          </React.Fragment>
        ))}
      </div>
      <div className="fs-9 mt-2" style={{ color: C.muted }}>% chance of each scoreline (home–away), Dixon-Coles adjusted. Darker = more likely.</div>
    </div>
  );
}
function TitleRaceChart({ projection }) {
  const data = projection.slice(0, 8).map((p) => ({ name: p.team.short, Title: p.titleProb, "Top 4": p.top4Prob - p.titleProb }));
  return (
    <ResponsiveContainer width="100%" height={260}>
      <BarChart data={data} layout="vertical" margin={{ left: 6, top: 4 }}>
        <CartesianGrid strokeDasharray="3 3" stroke={C.gridline} horizontal={false} />
        <XAxis type="number" tick={axisTick()} tickFormatter={(v) => `${Math.round(v * 100)}%`} axisLine={{ stroke: C.border }} tickLine={false} />
        <YAxis type="category" dataKey="name" tick={axisTick()} width={44} axisLine={false} tickLine={false} />
        <Tooltip contentStyle={tooltipStyle()} formatter={(v) => `${(v * 100).toFixed(1)}%`} />
        <Legend wrapperStyle={{ fontSize: 11 }} />
        <Bar dataKey="Title" stackId="a" fill={C.purple} radius={[0, 0, 0, 0]} />
        <Bar dataKey="Top 4" stackId="a" fill={C.lime} radius={[0, 4, 4, 0]} />
      </BarChart>
    </ResponsiveContainer>
  );
}

