function scrollToId(id) { document.getElementById(id)?.scrollIntoView({ behavior: "smooth", block: "start" }); }
function DarkCard({ children, style, className = "", id }) {
  return <div id={id} className={`rounded-2xl ${className}`} style={{ background: "rgba(24,14,43,0.72)", border: `1px solid ${PALETTE_DARK.border}`, backdropFilter: "blur(8px)", ...style }}>{children}</div>;
}
function RadarOrbit() {
  const rings = [1, 0.76, 0.54, 0.33];
  return (
    <div className="radar-orbit-wrap">
      <svg width="100%" height="100%" viewBox="0 0 200 200" style={{ position: "absolute", inset: 0 }}>
        {rings.map((r, i) => (
          <circle key={i} cx="100" cy="100" r={100 * r} fill="none" stroke={i % 2 === 0 ? PALETTE_DARK.purple : PALETTE_DARK.cyan}
            strokeOpacity={0.4 - i * 0.06} strokeWidth={i === 0 ? 1.4 : 0.8} strokeDasharray={i % 2 === 1 ? "3 6" : "none"} />
        ))}
        {Array.from({ length: 12 }).map((_, i) => {
          const a = (i / 12) * Math.PI * 2;
          const r = 100 * rings[(i % 3) + 1];
          const x = 100 + Math.cos(a) * r, y = 100 + Math.sin(a) * r;
          return <circle key={i} cx={x} cy={y} r={i % 3 === 0 ? 2.6 : 1.6} fill={i % 3 === 0 ? PALETTE_DARK.limeNeon : PALETTE_DARK.cyan} opacity={0.85} />;
        })}
      </svg>
      <div style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center" }}>
        <div className="crest-pulse" style={{
          width: "34%", height: "34%", borderRadius: "50%", padding: "4.5%",
          background: `radial-gradient(circle at 32% 28%, ${PALETTE_DARK.purple}, ${PALETTE_DARK.purpleDark})`,
          display: "flex", alignItems: "center", justifyContent: "center",
          boxShadow: `0 0 50px ${PALETTE_DARK.limeNeon}55, 0 0 0 2px ${PALETTE_DARK.limeNeon}77`,
        }}>
          <img src={IMG_LION_LOGO} alt="EPL Predictor crest" style={{ width: "100%", height: "100%", objectFit: "contain" }} />
        </div>
      </div>
    </div>
  );
}
function StatCallout({ label, value, pos, delay = "0s" }) {
  return (
    <div className="pop-in" style={{ position: "absolute", animationDelay: delay, ...pos }}>
      <DarkCard style={{ padding: "8px 13px" }}>
        <div className="epl-mono text-lg font-bold leading-tight" style={{ color: PALETTE_DARK.limeNeon }}>{value}</div>
        <div className="fs-9 uppercase tracking-widest" style={{ color: "rgba(255,255,255,0.62)" }}>{label}</div>
      </DarkCard>
    </div>
  );
}
function FactorBar({ label, value }) {
  return (
    <div className="mb-2.5">
      <div className="flex justify-between fs-11 mb-1" style={{ color: "rgba(255,255,255,0.68)" }}>
        <span>{label}</span><span className="font-semibold" style={{ color: "#fff" }}>{value}%</span>
      </div>
      <div className="w-full rounded-full overflow-hidden" style={{ height: 6, background: "rgba(255,255,255,0.12)" }}>
        <div style={{ width: `${value}%`, height: "100%", background: `linear-gradient(90deg, ${PALETTE_DARK.purple}, ${PALETTE_DARK.limeNeon})` }} />
      </div>
    </div>
  );
}
function MiniScoreCard({ fixture, settings }) {
  const p = predictMatch(fixture.home, fixture.away, settings);
  const conf = Math.max(p.pHome, p.pDraw, p.pAway);
  const pick = p.pHome === conf ? `${p.home.short} WIN` : p.pAway === conf ? `${p.away.short} WIN` : "DRAW";
  return (
    <DarkCard style={{ padding: 14, minWidth: 150 }}>
      <div className="flex items-center justify-between mb-2">
        <Crest team={p.home} size={26} />
        <span className="epl-mono text-base font-bold" style={{ color: "#fff" }}>{p.top[0].score}</span>
        <Crest team={p.away} size={26} />
      </div>
      <div className="fs-9 text-center mb-2 uppercase tracking-wide" style={{ color: "rgba(255,255,255,0.55)" }}>{p.home.short} vs {p.away.short}</div>
      <div className="text-center rounded-full py-1 fs-9 font-bold uppercase tracking-wide" style={{ background: `${PALETTE_DARK.limeNeon}22`, color: PALETTE_DARK.limeNeon }}>{pick} · {pct(conf)}</div>
    </DarkCard>
  );
}
